export const personalStatuses=['PLANNED','ACTIVE','COMPLETED','SKIPPED','MOVED'];
export const validDate=value=>typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&!Number.isNaN(Date.parse(value+'T12:00:00Z'))&&new Date(value+'T12:00:00Z').toISOString().slice(0,10)===value;
export const validTime=value=>typeof value==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(value);
export function validatePersonalBlock(b,recurring=false){if(!b.name?.trim()||b.name.length>100)throw Error('Enter a personal-time label.');if(!validDate(b.date)||!validTime(b.time))throw Error('Enter a valid date and time.');if(!Number.isFinite(b.durationMinutes)||b.durationMinutes<1||b.durationMinutes>1440)throw Error('Duration must be 1–1440 minutes.');if(!personalStatuses.includes(b.status||'PLANNED'))throw Error('Invalid Personal Time status.');if(recurring&&(!Array.isArray(b.weekdays)||!b.weekdays.length||b.weekdays.some(d=>!Number.isInteger(d)||d<0||d>6)))throw Error('Select valid recurrence days.');if(b.until&&(!validDate(b.until)||b.until<b.date))throw Error('Recurrence end must follow the start.');return true}
export function eventStart(e){return new Date(e.date+'T'+e.time+':00')}
export function availableWindow(events,now=new Date()){const upcoming=events.filter(e=>!['SKIPPED','COMPLETED','MISSED'].includes(e.status)&&e.date&&e.time).map(e=>{const start=eventStart(e).getTime()-(e.buffer||0)*60000,end=eventStart(e).getTime()+(e.durationMinutes||30)*60000;return {event:e,start,end}}).filter(e=>e.end>now.getTime()).sort((a,b)=>a.start-b.start);const next=upcoming[0];if(!next)return {minutes:120,event:null,reason:'No upcoming commitment is logged; verify your available time.'};const minutes=Math.max(0,Math.floor((next.start-now.getTime())/60000));return {minutes,event:next.event,reason:next.event.category==='Personal Time'?`${next.event.name} ${minutes===0?'is active now':'begins in '+minutes+' minutes'}. Protected personal time comes first.`:`${next.event.name} begins in ${minutes} minutes, including its buffer.`}}
export function overlapsProtected(events,date,time,durationMinutes){const start=new Date(date+'T'+time+':00').getTime(),end=start+durationMinutes*60000;return events.filter(e=>e.category==='Personal Time'&&e.protected&&!['SKIPPED','COMPLETED'].includes(e.status)&&start<eventStart(e).getTime()+(e.durationMinutes||30)*60000&&end>eventStart(e).getTime())}
export function weeklyPersonalSummary(events,now=new Date()){const end=new Date(now),start=new Date(now);start.setHours(0,0,0,0);start.setDate(start.getDate()-((start.getDay()+6)%7));return {completed:events.filter(e=>e.category==='Personal Time'&&e.status==='COMPLETED'&&eventStart(e)>=start&&eventStart(e)<=end).length,text:'Protected personal time is worthwhile on its own. No relationship streaks or duration rewards.'}}
